//! Chunk 51, finding r2cli#1: a stranger's piles of tokens, sorted ahead of
//! the user's own UTxOs, take every one of the 20 a CLI spend draws on.
//!
//! The CLI asks Koios for the contract's UTxOs in `order=tx_hash.asc,
//! tx_index.asc` (seedelf-koios `utxo_pages`, since 48a4c977), and a payer
//! chooses its transaction's hash: varying a metadata nonce some 65,536 times
//! gives one starting 0x0000, below every hash the user holds. Each of that
//! transaction's 20 outputs pays the contract under a re-randomization of the
//! user's register, which sits on chain beside their Seedelf, so the user's key
//! owns them all. Each holds 30 one-of tokens of a policy of its own and the
//! least ADA the CLI gives such a contract output (about 1.99 ₳), less than
//! the outputs the CLI splits its tokens into, 20 to an output, need. The 20
//! cost the stranger about 40 ₳.
//!
//! The user holds 500 ₳ of their own in five UTxOs. Every command that pays
//! must still pay from them: `sweep --all` sends them (it sends "the first 20
//! it can spend together … run it again for the rest", the README says), and
//! `sweep -l`, `sweep --utxo`, `transfer` and `util mint` pay from them. Each
//! case runs first as a control, with the stranger's hash above the user's,
//! which must pay, then with it below.
//!
//! The mock answers `credential_utxos` as PostgREST does: in the order the
//! request names, and with none named, in the order the rows were added (the
//! user's first, the stranger's later). Drives the real commands against the
//! CLI's offline mock Koios, reusing `tests/cli/harness.rs` as is.

#[path = "cli/harness.rs"]
mod harness;

use std::cmp::Ordering;

use blstrs::Scalar;
use harness::*;
use pallas_crypto::hash::Hasher;
use seedelf_cli::commands::sweep::{self, SweepArgs};
use seedelf_cli::commands::transfer::{self, TransforArgs};
use seedelf_cli::commands::util::mint::{self, MintArgs};
use seedelf_core::assets::{Asset as CoreAsset, Assets};
use seedelf_core::build::minimum_address_payment;
use seedelf_core::transaction::wallet_minimum_lovelace_with_assets;
use seedelf_koios::koios::UtxoResponse;
use serde_json::json;
use wiremock::matchers::{method, path};
use wiremock::{Mock, Request, Respond, ResponseTemplate};

const TEN_ADA: u64 = 10_000_000;

/// `credential_utxos` as PostgREST answers it: in the order the request's
/// `order` names, and with none, in the order the rows were added. One page
/// holds them all, so a later one (after the last row, or at an offset) is
/// empty.
struct AsKoiosOrders(Vec<UtxoResponse>);

impl Respond for AsKoiosOrders {
    fn respond(&self, request: &Request) -> ResponseTemplate {
        let query: Vec<(String, String)> = request
            .url
            .query_pairs()
            .map(|(k, v)| (k.into_owned(), v.into_owned()))
            .collect();
        if query
            .iter()
            .any(|(k, v)| k == "or" || (k == "offset" && v != "0"))
        {
            return ResponseTemplate::new(200).set_body_json(json!([]));
        }
        let mut rows = self.0.clone();
        if let Some((_, order)) = query.iter().find(|(k, _)| k == "order") {
            let keys: Vec<(&str, bool)> = order
                .split(',')
                .map(|key| {
                    let mut parts = key.split('.');
                    let column = parts.next().unwrap_or_default();
                    (column, parts.any(|p| p == "desc"))
                })
                .collect();
            rows.sort_by(|a, b| {
                keys.iter()
                    .fold(Ordering::Equal, |so_far, (column, descending)| {
                        so_far.then_with(|| {
                            let by = match *column {
                                "tx_hash" => a.tx_hash.cmp(&b.tx_hash),
                                "tx_index" => a.tx_index.cmp(&b.tx_index),
                                "block_height" => a.block_height.cmp(&b.block_height),
                                "block_time" => a.block_time.cmp(&b.block_time),
                                other => panic!("this mock can't order by {other}"),
                            };
                            if *descending { by.reverse() } else { by }
                        })
                    })
            });
        }
        ResponseTemplate::new(200).set_body_json(serde_json::to_value(&rows).expect("utxo json"))
    }
}

/// A 32-byte hash, in hex, made from `seed`.
fn hash_of(seed: &str) -> String {
    hex::encode(Hasher::<256>::hash(seed.as_bytes()))
}

fn as_assets(tokens: &[TokenAmount]) -> Assets {
    tokens.iter().fold(Assets::new(), |all, (policy, name, qty)| {
        all.add(CoreAsset::new(policy.clone(), name.clone(), *qty).expect("asset"))
            .expect("assets")
    })
}

/// The contract's UTxOs, in the order they were added, and the user's own
/// outpoints among them.
struct Contract {
    rows: Vec<UtxoResponse>,
    users: Vec<(String, u64)>,
    strangers_hash: String,
}

/// The user's five UTxOs of 100 ₳ and their Seedelf, from earlier blocks; then
/// the stranger's one transaction, its hash starting `strangers_prefix`: 20
/// piles of 30 tokens under re-randomizations of the user's register.
fn the_contract(scalar: Scalar, strangers_prefix: &str) -> Contract {
    let params = recorded_params();
    let mut rows = Vec::new();
    let mut users = Vec::new();
    for i in 0..5u64 {
        let mut row = wallet_utxo(scalar, 0, 100_000_000, &[]);
        row.tx_hash = hash_of(&format!("the user's payment {i}"));
        row.block_height = 3_000_000 + i;
        users.push((row.tx_hash.clone(), row.tx_index));
        rows.push(row);
    }
    // The Seedelf whose register the stranger read; a transfer pays it.
    let mut seedelf = seedelf_utxo(scalar, 0, 1_500_000, SAMPLE_SEEDELF);
    seedelf.tx_hash = hash_of("the user's seedelf");
    seedelf.block_height = 2_900_000;
    rows.push(seedelf);

    let strangers_hash = format!(
        "{strangers_prefix}{}",
        &hash_of("the stranger's transaction")[strangers_prefix.len()..]
    );
    for i in 0..20u8 {
        let tokens = pile(0x10 + i, 30);
        let least =
            wallet_minimum_lovelace_with_assets(&params, as_assets(&tokens)).expect("least");
        // A pile brings less than the outputs its tokens need at an address
        // (rows.rs `worth` < 0): the CLI can't send it on its own ADA.
        let needs = minimum_address_payment(&params, &external_address(), &as_assets(&tokens))
            .expect("address payment");
        assert!(least < needs, "a pile holds {least}, its outputs need {needs}");
        let mut row = wallet_utxo(scalar, 0, least, &tokens);
        row.tx_hash = strangers_hash.clone();
        row.tx_index = u64::from(i);
        row.block_height = 3_100_000;
        rows.push(row);
    }
    Contract {
        rows,
        users,
        strangers_hash,
    }
}

#[derive(Debug, Clone, Copy)]
enum Command {
    SweepAll,
    SweepTen,
    SweepTenFromOwnUtxo,
    TransferTen,
    Mint,
}

/// What a run did: its error, if any, and the transaction it sent.
struct Went {
    error: Option<String>,
    sent: Option<DecodedTx>,
    users_spent: Vec<(String, u64)>,
    users: Vec<(String, u64)>,
}

fn sweep_args(lovelace: Option<u64>, all: bool, utxos: Option<Vec<String>>) -> SweepArgs {
    SweepArgs {
        address: Some(external_address_bech32()),
        lovelace,
        all,
        assets: vec![],
        ada_handle: None,
        utxos,
    }
}

async fn run(command: Command, strangers_prefix: &str) -> Went {
    let mut scenario = Scenario::start().await;
    let contract = the_contract(scenario.scalar, strangers_prefix);
    for user in &contract.users {
        let below = contract.strangers_hash < user.0;
        assert_eq!(
            below,
            strangers_prefix == "0000",
            "the stranger's hash should sort {} the user's",
            if strangers_prefix == "0000" { "below" } else { "above" }
        );
    }
    // The harness's mount records every outpoint for the value checks; the
    // answer itself comes from the ordering mock, ahead of the harness's.
    scenario.mount_credential_utxos(contract.rows.clone()).await;
    Mock::given(method("POST"))
        .and(path("/api/v1/credential_utxos"))
        .respond_with(AsKoiosOrders(contract.rows.clone()))
        .with_priority(1)
        .mount(&scenario.server)
        .await;
    scenario.mount_evaluate_mint(20).await;
    scenario.mount_collateral().await;
    scenario.mount_submit().await;

    let result = match command {
        Command::SweepAll => sweep::run(sweep_args(None, true, None), PREPROD, VARIANT).await,
        Command::SweepTen => {
            sweep::run(sweep_args(Some(TEN_ADA), false, None), PREPROD, VARIANT).await
        }
        Command::SweepTenFromOwnUtxo => {
            let (hash, index) = &contract.users[0];
            let own = vec![format!("{hash}#{index}")];
            sweep::run(sweep_args(Some(TEN_ADA), false, Some(own)), PREPROD, VARIANT).await
        }
        Command::TransferTen => {
            transfer::run(
                TransforArgs {
                    seedelfs: vec![SAMPLE_SEEDELF.to_string()],
                    lovelaces: Some(vec![TEN_ADA]),
                    assets: vec![],
                    utxos: None,
                },
                PREPROD,
                VARIANT,
            )
            .await
        }
        Command::Mint => {
            mint::run(
                MintArgs {
                    label: Some("r2cli".to_string()),
                    generator: None,
                    public_value: None,
                    utxos: None,
                },
                PREPROD,
                VARIANT,
            )
            .await
        }
    };

    let sent = if scenario.requests_to("/api/v1/submittx").await > 0 {
        let tx = decode_tx(&scenario.submitted_cbor().await);
        assert_sound_transaction(&tx, &scenario, &protocol_params().await);
        Some(tx)
    } else {
        None
    };
    let users_spent = sent.as_ref().map_or(Vec::new(), |tx| {
        contract
            .users
            .iter()
            .filter(|u| tx.inputs.contains(u))
            .cloned()
            .collect()
    });
    Went {
        error: result.err().map(|e| format!("{e:#}")),
        sent,
        users_spent,
        users: contract.users,
    }
}

/// Why `went` isn't what `command` must do with the user's 500 ₳, if it isn't.
fn wrong(command: Command, went: &Went) -> Option<String> {
    let Some(tx) = &went.sent else {
        return Some(format!(
            "sent nothing: {}",
            went.error.as_deref().unwrap_or("no error")
        ));
    };
    if let Some(error) = &went.error {
        return Some(format!("sent, then failed: {error}"));
    }
    let to_address: Vec<&DecodedOutput> = tx.outputs_to(&external_address());
    match command {
        Command::SweepAll if went.users_spent.len() != went.users.len() => Some(format!(
            "spent {} of the user's 5 UTxOs",
            went.users_spent.len()
        )),
        Command::SweepAll if to_address.len() != tx.outputs.len() => {
            Some("sent some of it elsewhere than the address".to_string())
        }
        Command::SweepTen | Command::SweepTenFromOwnUtxo
            if !to_address.iter().any(|o| o.lovelace == TEN_ADA) =>
        {
            Some("didn't pay the address 10 ADA".to_string())
        }
        Command::SweepTenFromOwnUtxo if tx.inputs != vec![went.users[0].clone()] => {
            Some(format!("spent {:?}, not the UTxO named", tx.inputs))
        }
        _ if went.users_spent.is_empty() => Some("spent none of the user's UTxOs".to_string()),
        _ => None,
    }
}

#[tokio::test]
async fn a_strangers_piles_at_the_lowest_hashes_never_hold_back_the_users_own_ada() {
    let params = recorded_params();
    let pile_ada = wallet_minimum_lovelace_with_assets(&params, as_assets(&pile(0x10, 30)))
        .expect("least");
    let needs = minimum_address_payment(&params, &external_address(), &as_assets(&pile(0x10, 30)))
        .expect("address payment");
    eprintln!(
        "each pile: 30 tokens, {pile_ada} lovelace (its outputs at an address need {needs}); \
         the 20 cost the stranger {} lovelace",
        20 * pile_ada
    );

    let commands = [
        Command::SweepAll,
        Command::SweepTen,
        Command::SweepTenFromOwnUtxo,
        Command::TransferTen,
        Command::Mint,
    ];
    let mut failures = Vec::new();
    for command in commands {
        // The control: the stranger's hash above the user's, so Koios lists
        // the user's UTxOs first.
        let control = run(command, "ffff").await;
        if let Some(why) = wrong(command, &control) {
            panic!("control {command:?}, the user's UTxOs listed first, {why}");
        }
        let attacked = run(command, "0000").await;
        let verdict = wrong(command, &attacked);
        eprintln!(
            "{command:?}: control sent, spending {} of the user's UTxOs; with the stranger's \
             hash below the user's: {}",
            control.users_spent.len(),
            match &verdict {
                None => format!("sent, spending {} of the user's UTxOs", attacked.users_spent.len()),
                Some(why) => why.clone(),
            }
        );
        if let Some(why) = verdict {
            failures.push(format!("{command:?} {why}"));
        }
    }
    assert!(
        failures.is_empty(),
        "with 20 of a stranger's piles at the lowest hashes, the user's 500 ADA must still move:\n{}",
        failures.join("\n")
    );
}

//! Chunk 51, r2sign#1: the sign window calls a payment into Seedelf Wallet's
//! contract a Seedelf payment ("register": "It pays a Seedelf. Nothing on
//! chain says whose…", and no warning) only where a Seedelf Wallet will find
//! it and can spend it. This round's reader (cip30 `spender`, over Pallas's
//! data, and over the datum the witness set carries for an output's hash)
//! calls two shapes "register" that no Seedelf Wallet reads:
//! - constructor 0's general form with an indefinite pair, `102([_ 0, [g, u]])`,
//!   which the node decodes as `Constr 0 [g, u]` and keeps as written
//!   (cardano-cli 11.0.0.0, offline);
//! - a datum kept by hash, carried in the witness set, which isn't signed.
//!
//! A Seedelf Wallet reads a contract row's register from its inline datum's
//! bytes with seedelf-koios `register_of_datum` (the WebAssembly's
//! `check_spendable` and `remove_spend`, core's `ScriptSpend`, the CLI; the
//! worker's chain.ts `registerOf` is its twin), and a Koios row has no inline
//! datum for an output that keeps its datum by hash. Transaction details'
//! `payable` (decode.rs `register_detail`) has the same gap for the indefinite
//! pair: under the user's own register, tx-view.ts `markYours` says "Yours, in
//! your private balance". This asserts the right behaviour, so it fails while
//! the bug is there.

use pallas_addresses::Address;
use pallas_crypto::hash::{Hash, Hasher};
use pallas_primitives::{Fragment, PlutusData};
use seedelf_core::build::{self, Chain, ScriptSpend};
use seedelf_core::constants::get_config;
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{ProtocolParameters, UtxoResponse, extract_bytes_with_logging};
use seedelf_wasm::cip30::{self, KeyPath, KoiosRow, TxRequest};
use seedelf_wasm::decode::decode_tx;
use serde_json::{Value, json};

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const TX_A: &str = "1111111111111111111111111111111111111111111111111111111111111111";

fn account() -> CardanoAccount {
    CardanoAccount::from_phrase(PHRASE, 0).unwrap()
}

/// A CBOR byte string: its head, then the bytes.
fn bstr(b: &[u8]) -> String {
    let head = match b.len() {
        n if n < 24 => format!("{:02x}", 0x40 + n),
        n if n < 0x100 => format!("58{n:02x}"),
        n => format!("59{n:04x}"),
    };
    format!("{head}{}", hex::encode(b))
}

/// A post-Alonzo output, written by hand: Pallas would write a tag-102 pair
/// back definite, and the site's bytes are what's signed and put on chain.
fn output(address: &Address, lovelace: u32, datum_option: Option<String>) -> String {
    let address = bstr(&address.to_vec());
    match datum_option {
        Some(option) => format!("a300{address}011a{lovelace:08x}02{option}"),
        None => format!("a200{address}011a{lovelace:08x}"),
    }
}

#[test]
fn a_payment_the_window_calls_a_seedelfs_is_one_a_seedelf_wallet_finds_and_spends() {
    // The receiving Seedelf's register, re-randomized as a payment's is: u = g^sk.
    let sk = random_scalar();
    let owner = Register::create(sk).unwrap().rerandomize().unwrap();
    assert!(build::is_payable(&owner));
    // 121([_ g, u]), as the wallet writes it, and the general form both ways.
    let canonical = owner.to_vec().unwrap();
    assert_eq!(hex::encode(&canonical[..3]), "d8799f");
    let fields = &canonical[3..canonical.len() - 1];
    let definite_pair = [&[0xd8, 0x66, 0x82, 0x00, 0x82][..], fields].concat();
    let indefinite_pair = [&[0xd8, 0x66, 0x9f, 0x00, 0x82][..], fields, &[0xff]].concat();
    // All three are the same Plutus data, Constr 0 [g, u], to Pallas as to the
    // node: the contract reads them alike, and only sk's holder can spend.
    let data = |b: &[u8]| PlutusData::decode_fragment(b).unwrap();
    assert_eq!(data(&definite_pair), data(&canonical));
    assert_eq!(data(&indefinite_pair), data(&canonical));
    let kept = Hasher::<256>::hash(&canonical);

    // A site's transaction: the account's 10 ₳ pays 2 ₳ into the contract four
    // ways, under the same register, and the rest back to its change address.
    let config = get_config(1, true).unwrap();
    let contract_hash = config.contract.wallet_contract_hash;
    let contract = seedelf_core::address::wallet_contract(true, contract_hash);
    let change = account().base_address(true, Role::Change, 0).unwrap();
    let inline = |d: &[u8]| format!("8201d818{}", bstr(d));
    let outputs = [
        output(&contract, 2_000_000, Some(inline(&canonical))),
        output(&contract, 2_000_000, Some(inline(&definite_pair))),
        output(&contract, 2_000_000, Some(inline(&indefinite_pair))),
        output(&contract, 2_000_000, Some(format!("8200{}", bstr(kept.as_ref())))),
        output(&change, 1_800_000, None),
    ];
    let body = format!(
        "a30081825820{TX_A}0001{:02x}{}021a{:08x}",
        0x80 + outputs.len(),
        outputs.concat(),
        200_000
    );
    // The witness set carries the datum the fourth output keeps by hash.
    let tx = format!("84{body}a10481{}f5f6", hex::encode(&canonical));
    assert!(tx.contains(&format!("d818{}", bstr(&indefinite_pair))), "the pair as written");

    let input: KoiosRow = serde_json::from_value(json!({
        "tx_hash": TX_A, "tx_index": 0,
        "address": account().base_address(true, Role::Receive, 0).unwrap().to_bech32().unwrap(),
        "value": "10000000", "asset_list": [],
    }))
    .unwrap();
    let request = TxRequest {
        network: "preprod".into(),
        tx_cbor: tx.clone(),
        keys: (0..3)
            .flat_map(|index| [KeyPath { role: 0, index }, KeyPath { role: 1, index }])
            .collect(),
        inputs: vec![input],
        partial_sign: false,
        stake_index: 0,
        stake_deposit: None,
        governance: false,
    };
    let summary = cip30::inspect_tx(&account(), &request).unwrap();
    assert_eq!(summary.paid.len(), 4, "the change is the account's own");
    let datums: Vec<_> = summary.paid.iter().map(|p| p.datum.as_deref()).collect();
    assert_eq!(datums, [Some("inline"), Some("inline"), Some("inline"), Some("hash")]);
    let detail = decode_tx("preprod", &tx).unwrap();

    // Each output as Koios lists it once it's on chain.
    let rows: Vec<UtxoResponse> = (0..4u64)
        .map(|index| {
            let written: Option<&[u8]> = match index {
                0 => Some(&canonical),
                1 => Some(&definite_pair),
                2 => Some(&indefinite_pair),
                _ => None,
            };
            let hash = written.map_or(kept, Hasher::<256>::hash);
            serde_json::from_value(json!({
                "tx_hash": summary.tx_hash, "tx_index": index,
                "address": contract.to_bech32().unwrap(), "value": "2000000",
                "stake_address": null, "payment_cred": hex::encode(contract_hash),
                "epoch_no": 0, "block_height": 0, "block_time": 0,
                "datum_hash": hex::encode(hash.as_ref()),
                "inline_datum": written.map(|b| json!({ "bytes": hex::encode(b), "value": null })),
                "reference_script": null, "asset_list": [], "is_spent": false,
            }))
            .unwrap()
        })
        .collect();

    // What a Seedelf Wallet does with such a row: reads its register from the
    // inline datum, owns it by sk, and spends it (core's `ScriptSpend`).
    let epoch: Value = serde_json::from_str(include_str!(
        "../../../seedelf-core/tests/fixtures/epoch_params.json"
    ))
    .unwrap();
    let chain = Chain {
        params: ProtocolParameters::from_koios(&epoch[0]).unwrap(),
        network_flag: true,
        config: get_config(1, true).unwrap(),
    };
    let signer = Hash::<28>::new([7; 28]);
    let finds = |row: &UtxoResponse| {
        extract_bytes_with_logging(&row.inline_datum)
            .is_some_and(|r| build::is_payable(&r) && r.is_owned(sk).unwrap_or(false))
            && ScriptSpend::new(&chain, std::slice::from_ref(row), &owner, signer).is_ok()
    };

    // Controls, which hold today: the two spellings the wallet reads are found,
    // spent and called a Seedelf payment, in the window and in the details.
    for i in 0..2 {
        assert!(finds(&rows[i]), "output {i} is found and spent");
        assert_eq!(summary.paid[i].seedelf.as_deref(), Some("register"));
    }

    let names = [
        "121([_ g, u]) inline, as the wallet writes it",
        "102([0, [g, u]]) inline",
        "102([_ 0, [g, u]]) inline, an indefinite pair",
        "kept by hash, the datum carried in the witness set",
    ];
    let mut wrong = Vec::new();
    for (i, name) in names.iter().enumerate() {
        let found = finds(&rows[i]);
        let wallet = if found { "finds and spends it" } else { "never finds or spends it" };
        let window = summary.paid[i].seedelf.as_deref();
        if (window == Some("register")) != found {
            wrong.push(format!(
                "sign window: output {i}, {name}, reads {window:?} (\"It pays a Seedelf…\", no warning), \
                 while a Seedelf Wallet {wallet}"
            ));
        }
        // tx-view.ts markYours: the contract, `register.payable`, and the user's key.
        let yours = detail.outputs[i].address.seedelf
            && detail.outputs[i].register.as_ref().is_some_and(|r| {
                r.payable
                    && Register::new(r.generator.clone(), r.public_value.clone())
                        .is_owned(sk)
                        .unwrap_or(false)
            });
        if yours != found {
            wrong.push(format!(
                "Transaction details: output {i}, {name}, reads payable under the user's key: {yours} \
                 (\"Yours, in your private balance\"), while a Seedelf Wallet {wallet}"
            ));
        }
    }
    assert!(wrong.is_empty(), "{wrong:#?}");
}

//! Chunk 51, finding r2cli#2: r2b#2's fix sorts every UTxO holding a token
//! being sent ahead of the ADA-only ones (utxos.rs `SelectOrder`,
//! `(!holds_sent, has_tokens, Reverse(lovelace))`). Once the first holder has
//! brought all of the token sent, `do_select`'s third branch ("you need ada
//! because you already found the tokens") takes the next holder for its ADA
//! before any ADA-only UTxO is reached. That holder's other tokens join the
//! change, and the change's floor (one output's least for all of them, times
//! the outputs at 20 tokens each) raises the goal past what the address holds.
//!
//! This runs `fund`'s own steps (fund.rs:124-142): `collect_address_utxos`,
//! no reference scripts, `fitting`, then `select` with the lovelace and the
//! tokens asked for: `fund -l <lovelace> --asset <T>=100`.

use seedelf_core::assets::{Asset, Assets};
use seedelf_core::constants::MAXIMUM_TOKENS_PER_UTXO;
use seedelf_core::transaction::wallet_minimum_lovelace_with_assets;
use seedelf_core::utxos;
use seedelf_koios::koios::{Asset as KoiosAsset, ProtocolParameters, Ratio, UtxoResponse};

const T_POLICY: &str = "11111111111111111111111111111111111111111111111111111111";
const ADA: u64 = 1_000_000;

fn fixture_params() -> ProtocolParameters {
    ProtocolParameters {
        min_fee_a: 44,
        min_fee_b: 155_381,
        coins_per_utxo_size: 4_310,
        key_deposit: 2_000_000,
        drep_deposit: Some(500_000_000),
        price_mem: 0.0577,
        price_step: 0.0000721,
        cost_model_v3: Vec::new(),
        cost_model_v1: Vec::new(),
        cost_model_v2: Vec::new(),
        min_fee_ref_script_cost_per_byte: Ratio::whole(15),
    }
}

/// A UTxO at the paying address, made by the transaction `[byte; 32]`.
fn row(byte: u8, lovelace: u64, tokens: &[(String, &str, u64)]) -> UtxoResponse {
    UtxoResponse {
        tx_hash: hex::encode([byte; 32]),
        value: lovelace.to_string(),
        asset_list: Some(
            tokens
                .iter()
                .map(|(policy, name, quantity)| KoiosAsset {
                    policy_id: policy.clone(),
                    asset_name: (*name).to_string(),
                    quantity: quantity.to_string(),
                    ..Default::default()
                })
                .collect(),
        ),
        ..Default::default()
    }
}

fn label(u: &UtxoResponse) -> String {
    format!("U{}", u8::from_str_radix(&u.tx_hash[..2], 16).unwrap())
}

fn labels(picked: &[UtxoResponse]) -> Vec<String> {
    picked.iter().map(label).collect()
}

/// `--asset <T_POLICY>.aa=100`
fn sent() -> Assets {
    Assets::new()
        .add(Asset::new(T_POLICY.to_string(), "aa".to_string(), 100).unwrap())
        .unwrap()
}

#[test]
fn r51_r2cli_2_fund_takes_ada_only_rows_before_a_second_holder_of_the_token_sent() {
    let params = fixture_params();

    // U1: 20 ₳ and the 100 T sent. U2: 9.4 ₳, 1 T and 60 NFTs of 60 policies.
    // U3: 100 ₳ alone. 129.4 ₳ and 101 T in all.
    let mut u2_tokens: Vec<(String, &str, u64)> = vec![(T_POLICY.to_string(), "aa", 1)];
    for i in 0..60u8 {
        u2_tokens.push((hex::encode([0x40 + i; 28]), "01", 1));
    }
    let u1 = row(0x01, 20 * ADA, &[(T_POLICY.to_string(), "aa", 100)]);
    let u2 = row(0x02, 9_400_000, &u2_tokens);
    let u3 = row(0x03, 100 * ADA, &[]);

    // fund.rs:124-136: no pure 5 ₳ row, no reference script, nothing overflows.
    let usable = utxos::collect_address_utxos(vec![u1.clone(), u2.clone(), u3.clone()]).unwrap();
    let usable: Vec<UtxoResponse> = usable
        .into_iter()
        .filter(|u| u.reference_script.is_none())
        .collect();
    let (usable, left) = utxos::fitting(&usable, &Assets::new(), |_| false).unwrap();
    assert_eq!(
        (labels(&usable), left.len()),
        (
            vec!["U1".to_string(), "U2".to_string(), "U3".to_string()],
            0
        ),
        "fund hands select all three rows"
    );

    // The floors select's check (utxos.rs:315-336) sets: no change tokens with
    // U1 and U3; U2's 61 tokens once U2 joins.
    let ada_change_least = wallet_minimum_lovelace_with_assets(&params, Assets::new()).unwrap();
    let u2_change = utxos::assets_of(vec![u2.clone()]).unwrap().1;
    let kinds = u2_change.len();
    let multiplier = if kinds > MAXIMUM_TOKENS_PER_UTXO {
        kinds / MAXIMUM_TOKENS_PER_UTXO + 1
    } else {
        1
    };
    let u2_floor = multiplier * wallet_minimum_lovelace_with_assets(&params, u2_change).unwrap();
    println!(
        "R51_R2CLI_2 floors: ADA-only change {ada_change_least}; with U2's {kinds} tokens {multiplier} x one output's least = {u2_floor}"
    );

    // Control: under select's own rule, U1 and U3 pay 100 ₳ and the 100 T.
    let control = utxos::select(&params, vec![u1.clone(), u3.clone()], 100 * ADA, sent()).unwrap();
    println!(
        "R51_R2CLI_2 control, U1 and U3 alone, 100 ₳: {:?}",
        labels(&control)
    );
    assert!(
        !control.is_empty(),
        "U1 and U3 alone pay 100 ₳ and the 100 T"
    );

    // `fund -l 100000000 --asset <T>=100`, and the same with -l 50000000.
    let picked_100 = utxos::select(&params, usable.clone(), 100 * ADA, sent()).unwrap();
    let picked_50 = utxos::select(&params, usable.clone(), 50 * ADA, sent()).unwrap();
    println!(
        "R51_R2CLI_2 picked for 100 ₳: {:?}; for 50 ₳: {:?}",
        labels(&picked_100),
        labels(&picked_50)
    );

    // What select promises when it picks (as r2b#2's test checks it).
    for (goal, picked) in [(100 * ADA, &picked_100), (50 * ADA, &picked_50)] {
        if picked.is_empty() {
            continue;
        }
        let (total, found) = utxos::assets_of(picked.clone()).unwrap();
        assert!(found.contains(sent()), "the pick holds the token sent");
        let change = found.separate(sent()).unwrap();
        let change_least = wallet_minimum_lovelace_with_assets(&params, change).unwrap();
        assert!(
            total >= goal + change_least,
            "picked {total} lovelace, short of the goal {goal} and the change's {change_least}"
        );
    }

    // Right: the token's holders go first only until the token sent is found;
    // ADA alone comes before any other token UTxO, so U2 is never needed.
    let refused = picked_100.is_empty();
    let spends_u2 = picked_100
        .iter()
        .chain(picked_50.iter())
        .any(|u| label(u) == "U2");
    assert!(
        !refused && !spends_u2,
        "the address holds 129.4 ₳ and 101 T, and U1 + U3 pay 100 ₳ and the 100 T with ADA-only \
         change (select picks {:?} from them alone), yet from all three select picked {:?} for \
         100 ₳ (an empty pick is fund's \"Not Enough Lovelace/Tokens\") and {:?} for 50 ₳: U2 \
         joined for its ADA ahead of U3, and its {kinds} tokens put the change's floor at \
         {u2_floor} lovelace",
        labels(&control),
        labels(&picked_100),
        labels(&picked_50),
    );
}

//! Chunk 51, r2money#1: a session's return merged into its funding's change,
//! whose only collateral is `session_collateral`'s fallback (the largest
//! ADA-only UTxO of 2 ₳ or more, the session's 5 ₳ being gone). A heavy
//! return's fee takes 3/2 of it past an output's least, so the merged form is
//! refused (21caa3b8's words), and nothing tries the plain sweep of the same
//! UTxOs, which runs no script, needs no collateral and builds.
//!
//! The right behaviour: the return still comes back, whole, in a transaction
//! the ledger takes. This test fails while `session_return` refuses it.

use pallas_addresses::Address;
use pallas_traverse::MultiEraTx;
use seedelf_core::address::wallet_contract;
use seedelf_core::constants::{VARIANT, get_config};
use seedelf_crypto::cardano::{CardanoAccount, ONE_TIME_ACCOUNT};
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{ProtocolParameters, UtxoResponse};
use seedelf_wasm::api::{self, SessionReturnRequest, SessionReturnResult};
use serde_json::{Value, json};

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const POLICY: &str = "e16c2dc8ae937e8d3790c7fd7168d7b994621ba14ca11415f39fed72";

fn accounts() -> CardanoAccount {
    CardanoAccount::from_phrase(PHRASE, ONE_TIME_ACCOUNT).unwrap()
}

fn params() -> Value {
    let rows: Value = serde_json::from_str(include_str!(
        "../../../seedelf-core/tests/fixtures/epoch_params.json"
    ))
    .unwrap();
    rows[0].clone()
}

/// A UTxO at `address` as Koios lists it.
fn utxo(tx: u8, address: &Address, lovelace: u64, tokens: &[(String, u64)]) -> UtxoResponse {
    let assets: Vec<Value> = tokens
        .iter()
        .map(|(n, q)| json!({ "policy_id": POLICY, "asset_name": n, "quantity": q.to_string(), "decimals": 0, "fingerprint": "" }))
        .collect();
    serde_json::from_value(json!({
        "tx_hash": hex::encode([tx; 32]),
        "tx_index": 0,
        "address": address.to_bech32().unwrap(),
        "value": lovelace.to_string(),
        "stake_address": null,
        "payment_cred": "",
        "epoch_no": 0,
        "block_height": 0,
        "block_time": 0,
        "datum_hash": null,
        "inline_datum": null,
        "reference_script": null,
        "asset_list": assets,
        "is_spent": false,
    }))
    .unwrap()
}

/// The change the session's funding left in the private balance, under a
/// fresh copy of `sk`'s register: what a return merges into.
fn funding_change(sk: blstrs::Scalar, lovelace: u64) -> UtxoResponse {
    let wallet = wallet_contract(
        true,
        get_config(VARIANT, true)
            .unwrap()
            .contract
            .wallet_contract_hash,
    );
    let register = Register::create(sk).unwrap().rerandomize().unwrap();
    let mut row = utxo(0xf0, &wallet, lovelace, &[]);
    row.inline_datum = serde_json::from_value(json!({
        "bytes": hex::encode(register.to_vec().unwrap()),
        "value": { "constructor": 0, "fields": [
            { "bytes": register.generator }, { "bytes": register.public_value },
        ]},
    }))
    .unwrap();
    row
}

/// What a site's session can hold after its 5 ₳ collateral was spent by a
/// site's transaction the user approved: 13 of the session's own UTxOs, each
/// 20 NFTs (32-byte names, as CIP-68's) and 6 ₳, which pays their deposit
/// outputs; and one ADA-only UTxO of `ada`, the only one, which is
/// `session_collateral`'s fallback when it's 2 ₳ or more. All of them are
/// the session's own (outputs of transactions its key signed).
fn account(at: &Address, ada: u64) -> (Vec<UtxoResponse>, Vec<String>) {
    let mut rows: Vec<UtxoResponse> = (0..13u8)
        .map(|i| {
            let nfts: Vec<(String, u64)> = (0..20u8)
                .map(|j| {
                    let mut name = [0x41u8; 32];
                    name[0] = i;
                    name[1] = j;
                    (hex::encode(name), 1)
                })
                .collect();
            utxo(0x10 + i, at, 6_000_000, &nfts)
        })
        .collect();
    rows.push(utxo(0xc0, at, ada, &[]));
    let own = rows.iter().map(|u| u.tx_hash.clone()).collect();
    (rows, own)
}

fn request(utxos: &[UtxoResponse], merge: &[UtxoResponse], own: &[String]) -> SessionReturnRequest {
    SessionReturnRequest {
        network: "preprod".into(),
        params: params(),
        index: 3,
        utxos: utxos.to_vec(),
        merge: merge.to_vec(),
        own: own.to_vec(),
        collateral_pool: None,
        collateral_boxes: vec![],
        rewards: Default::default(),
    }
}

/// The least an output of ADA alone holds at `at`.
fn least(at: &Address) -> u64 {
    let p = ProtocolParameters::from_koios(&params()).unwrap();
    seedelf_core::transaction::address_minimum_lovelace_with_assets(
        &p,
        &at.to_bech32().unwrap(),
        seedelf_core::assets::Assets::new(),
    )
    .unwrap()
}

/// That `built`'s transaction is one the ledger takes as to its collateral:
/// none (no script runs), or one that covers 3/2 of the fee and whose return
/// holds an output's least. Its fee.
fn collateral_holds(built: &SessionReturnResult, rows: &[UtxoResponse], least: u64) -> u64 {
    let bytes = hex::decode(&built.tx_cbor).unwrap();
    let tx = MultiEraTx::decode(&bytes).unwrap();
    let fee = tx.fee().unwrap();
    assert_eq!(fee.to_string(), built.fee);
    let put_up: u64 = tx
        .collateral()
        .iter()
        .map(|i| {
            rows.iter()
                .find(|u| u.tx_hash == hex::encode(**i.hash()) && u.tx_index == i.index())
                .expect("the collateral is one of the account's UTxOs")
                .value
                .parse::<u64>()
                .unwrap()
        })
        .sum();
    if put_up == 0 {
        assert!(tx.collateral_return().is_none());
        return fee;
    }
    let back = tx.collateral_return().map_or(0, |o| o.value().coin());
    assert!(
        back >= least,
        "the collateral comes back as {back} lovelace, under an output's least ({least}): the ledger refuses it"
    );
    assert!(
        2 * (put_up - back) >= 3 * fee,
        "the collateral covers 3/2 of the fee"
    );
    fee
}

#[test]
fn r51_r2money_1_a_merged_return_its_fallback_collateral_cant_cover_still_comes_back() {
    let accounts = accounts();
    let at = api::one_time_address(&accounts, true, 3).unwrap();
    let least = least(&at);
    let sk = random_scalar();
    let change = funding_change(sk, 10_000_000);

    // The account as the site left it: its only ADA-only UTxO is 2 ₳.
    let (rows, own) = account(&at, 2_000_000);

    // The plain sweep of these UTxOs builds: no script, no collateral, every UTxO in one transaction.
    let sweep = api::session_return(&accounts, sk, request(&rows, &[], &own))
        .expect("the plain sweep of the account's UTxOs builds");
    assert_eq!(sweep.merged, 0);
    assert_eq!(sweep.inputs, rows.len());
    assert!(sweep.left_out.is_empty());
    let sweep_fee = collateral_holds(&sweep, &rows, least);

    // The same account with a 3 ₳ ADA-only UTxO instead merges into the funding's change, under that collateral; its
    // fee takes 3/2 of a 2 ₳ one past an output's least, so 2 ₳ can't be this merged return's collateral.
    let (roomy, roomy_own) = account(&at, 3_000_000);
    let merged = api::session_return(&accounts, sk, request(&roomy, std::slice::from_ref(&change), &roomy_own))
        .expect("with 3 ₳ up, the merged return builds");
    assert_eq!(merged.merged, 1);
    let merged_fee = collateral_holds(&merged, &roomy, least);
    println!(
        "least {least}; sweep fee {sweep_fee}; merged fee {merged_fee}, 3/2 of it {}; a 2 ₳ collateral would come back as {}",
        merged_fee * 3 / 2,
        2_000_000i64 - (merged_fee * 3 / 2) as i64,
    );
    assert!(
        2_000_000 < least + merged_fee * 3 / 2,
        "the shape needs a merged return whose collateral a 2 ₳ one can't be"
    );

    // The bug: with the funding's change to merge into and only the 2 ₳ to put up, the return is refused, and nothing
    // falls back to the sweep that builds. Every Bring it back and every runner step is refused while this holds.
    let back = api::session_return(&accounts, sk, request(&rows, std::slice::from_ref(&change), &own));
    println!(
        "merged into the funding's change, 2 ₳ up: {}",
        match &back {
            Ok(b) => format!("built, fee {}, merged {}, inputs {}", b.fee, b.merged, b.inputs),
            Err(e) => format!("refused: {e}"),
        }
    );
    let back = back.unwrap_or_else(|e| {
        panic!("the return is refused, though the plain sweep of the same UTxOs builds (fee {sweep_fee}): {e}")
    });
    // Everything comes back, as the sweep shows one transaction holds it, in a transaction the ledger takes.
    assert!(back.left_out.is_empty(), "{:?}", back.left_out.len());
    assert_eq!(back.inputs, rows.len());
    collateral_holds(&back, &rows, least);
}

