//! Chunk 51, r2money#2. A session's return merged into its funding's change puts up the session's own collateral:
//! its 5 ₳ UTxO or, once a site's transaction spent that, the largest ADA-only one of 2 ₳ or more
//! (`session_collateral`). What that collateral gives back is an output, and the ledger holds it to an output's least
//! at the fee the transaction pays. A return whose settled fee leaves the least is a transaction the ledger takes, so
//! it's built. 21caa3b8 checks the least in every staging, the estimate's too, whose fee is priced on
//! SPEND_BUDGET_GUESS (about 1.3× what the wallet contract uses): a collateral within 3/2 of the guess's extra compute
//! above the settled fee's need is refused.

use pallas_addresses::Address;
use pallas_traverse::MultiEraTx;
use seedelf_core::address::wallet_contract;
use seedelf_core::constants::{VARIANT, get_config};
use seedelf_crypto::cardano::{CardanoAccount, ONE_TIME_ACCOUNT};
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{ProtocolParameters, UtxoResponse};
use seedelf_wasm::api::{self, SessionReturnRequest};
use serde_json::{Value, json};

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const POLICY: &str = "e16c2dc8ae937e8d3790c7fd7168d7b994621ba14ca11415f39fed72";
/// The session's own UTxOs holding tokens, 20 each: the return re-makes each as a deposit output of its own, so its
/// fee is heavy enough that 3/2 of it and the least pass 2 ₳.
const TOKEN_ROWS: u8 = 13;

fn params() -> Value {
    let rows: Value = serde_json::from_str(include_str!(
        "../../../seedelf-core/tests/fixtures/epoch_params.json"
    ))
    .unwrap();
    rows[0].clone()
}

fn row(tx: u8, address: &Address, lovelace: u64, names: &[String]) -> UtxoResponse {
    let assets: Vec<Value> = names
        .iter()
        .map(|n| json!({ "policy_id": POLICY, "asset_name": n, "quantity": "1", "decimals": 0, "fingerprint": "" }))
        .collect();
    serde_json::from_value(json!({
        "tx_hash": hex::encode([tx; 32]),
        "tx_index": 0,
        "address": address.to_bech32().unwrap(),
        "value": lovelace.to_string(),
        "stake_address": null,
        "payment_cred": "",
        "epoch_no": 0,
        "block_height": 0,
        "block_time": 0,
        "datum_hash": null,
        "inline_datum": null,
        "reference_script": null,
        "asset_list": assets,
        "is_spent": false,
    }))
    .unwrap()
}

/// The Seedelf change the session's funding made, under a fresh copy of `owner`.
fn funding_change(owner: &Register, lovelace: u64) -> UtxoResponse {
    let wallet = wallet_contract(
        true,
        get_config(VARIANT, true)
            .unwrap()
            .contract
            .wallet_contract_hash,
    );
    let register = owner.clone().rerandomize().unwrap();
    let mut change = row(0xf0, &wallet, lovelace, &[]);
    change.inline_datum = serde_json::from_value(json!({
        "bytes": hex::encode(register.to_vec().unwrap()),
        "value": { "constructor": 0, "fields": [
            { "bytes": register.generator }, { "bytes": register.public_value },
        ]},
    }))
    .unwrap();
    change
}

/// The session's account, all of it made by the session's own transactions: TOKEN_ROWS UTxOs of 20 tokens and 6 ₳,
/// and one of `collateral` lovelace, ADA alone. No 5 ₳ UTxO: a site's transaction spent it.
fn account(at: &Address, collateral: u64) -> (Vec<UtxoResponse>, Vec<String>) {
    let mut rows: Vec<UtxoResponse> = (0..TOKEN_ROWS)
        .map(|i| {
            let names: Vec<String> = (0..20u8)
                .map(|j| {
                    let mut name = [0x52u8; 32];
                    name[0] = i;
                    name[1] = j;
                    hex::encode(name)
                })
                .collect();
            row(0x10 + i, at, 6_000_000, &names)
        })
        .collect();
    rows.push(row(0xc0, at, collateral, &[]));
    let own = rows.iter().map(|r| r.tx_hash.clone()).collect();
    (rows, own)
}

#[test]
fn a_merged_return_whose_collateral_comes_back_with_its_least_at_the_fee_it_pays_is_built() {
    let accounts = CardanoAccount::from_phrase(PHRASE, ONE_TIME_ACCOUNT).unwrap();
    let index = 3;
    let at = api::one_time_address(&accounts, true, index).unwrap();
    let sk = random_scalar();
    let change = funding_change(&Register::create(sk).unwrap(), 10_000_000);
    let back = |collateral: u64| {
        let (utxos, own) = account(&at, collateral);
        api::session_return(
            &accounts,
            sk,
            SessionReturnRequest {
                network: "preprod".into(),
                params: params(),
                index,
                utxos,
                merge: vec![change.clone()],
                own,
                collateral_pool: None,
                collateral_boxes: vec![],
                rewards: Default::default(),
            },
        )
    };
    let p = ProtocolParameters::from_koios(&params()).unwrap();
    let least = seedelf_core::transaction::address_minimum_lovelace_with_assets(
        &p,
        &at.to_bech32().unwrap(),
        seedelf_core::assets::Assets::new(),
    )
    .unwrap();

    // The fee this return settles at, its collateral well clear of the least.
    let clear = back(3_000_000).expect("with 3 ₳ up, the merged return builds");
    assert_eq!(clear.merged, 1);
    assert_eq!(clear.inputs, usize::from(TOKEN_ROWS) + 1);
    let settled: u64 = clear.fee.parse().unwrap();

    // A collateral that pays 3/2 of that fee and gives back 5,000 lovelace over its least. It's the fallback's pick
    // (2 ₳ or more, not 5 ₳), and the proofs' budgets move the fee by far less than 5,000 / (3/2).
    let collateral = least + settled * 3 / 2 + 5_000;
    assert!(
        collateral >= 2_000_000 && collateral != 5_000_000,
        "{collateral}"
    );
    let built = back(collateral).unwrap_or_else(|e| {
        panic!(
            "refused: {e} (least {least}, settled fee {settled}, collateral {collateral}, which gives back {} at that fee)",
            collateral - settled * 3 / 2
        )
    });
    assert_eq!(built.merged, 1);
    assert_eq!(built.inputs, usize::from(TOKEN_ROWS) + 1);

    // The transaction the ledger takes: the collateral is that UTxO, 3/2 of the fee stays, and what comes back holds
    // at least an output's least, by the ledger's own rule on its bytes.
    let bytes = hex::decode(&built.tx_cbor).unwrap();
    let tx = MultiEraTx::decode(&bytes).unwrap();
    let fee = tx.fee().unwrap();
    assert_eq!(fee.to_string(), built.fee);
    let collaterals: Vec<_> = tx
        .collateral()
        .iter()
        .map(|i| (**i.hash(), i.index()))
        .collect();
    assert_eq!(collaterals, vec![([0xc0; 32], 0)]);
    let returned = tx.collateral_return().expect("a collateral return");
    assert_eq!(returned.address().unwrap().to_vec(), at.to_vec());
    let coin = returned.value().coin();
    assert_eq!(collateral - coin, fee * 3 / 2);
    let ledger_least = (160 + returned.encode().len() as u64) * 4_310;
    assert!(
        coin >= ledger_least && coin >= least,
        "{coin} < {ledger_least} / {least}"
    );
}

// Chunk 51's review of its own fixes, r2screens#1. e3b#2's fix (d9e015fb) holds the connect window's private-session
// form to the unlocked side of the private balance (DappApprovals.tsx:623, `setSeedelf(unlocked(b.seedelf))`), which is
// what the funding's build can spend. But the line under the amount and its "more than" note still call that side
// what's "in your private balance" (dappUi.heldAndCollateral, sites.topUp.tooMuch), and nothing in the window says
// what's locked: with 100 ₳ held and 60 ₳ of it locked, Home shows 100 ₳ with "60 ₳ locked" under it, and the window
// says "40 ₳ in your private balance". With everything locked it says "0 ₳ in your private balance". Chunk 12's rule
// (#23, archive/plans/chunk-12-style-flow.md:49): "the forms offer only what's unlocked ("3 ₳ available · 25 ₳ locked"),
// and say when everything is locked". e3b#2's verifier asked for it too (verify/e3b-2.md:77: lockedAside).
//
// Over the house's seam (screens-wiring-review-fixes.test.ts): ConnectRequest's own effects run during
// renderToStaticMarkup, `call` answers at once so its reading of the balances lands in the same render, and the private
// session's choice and the amount typed start as seeds in their useState.
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { beforeEach, describe, expect, it, vi } from "vitest";

const seam = vi.hoisted(() => {
  /** A thenable that answers at once: an effect's `.then` lands in the same render. */
  interface Answer {
    then(ok?: ((value: unknown) => unknown) | null, no?: ((error: unknown) => unknown) | null): Answer;
    catch(no: (error: unknown) => unknown): Answer;
    finally(done: () => void): Answer;
  }
  const answered = (value: unknown): Answer => ({
    then: (ok) => (ok ? answered(ok(value)) : answered(value)),
    catch: () => answered(value),
    finally: (done) => {
      done();
      return answered(value);
    },
  });
  /** Never answers: a request the test leaves unanswered. */
  const pending: Answer = { then: () => pending, catch: () => pending, finally: () => pending };
  const state = {
    /** The components whose own effects run, by name. */
    effects: new Set<string>(),
    answers: new Map<string, unknown>(),
    asked: [] as string[],
    /** A useState seeded: the call right after a run of calls starting as `after`, itself starting as `initial`. */
    seeds: [] as Array<{ after: unknown[]; initial: unknown; value: unknown; used?: true }>,
    initials: [] as unknown[],
    call(type: string): Answer {
      state.asked.push(type);
      return state.answers.has(type) ? answered(state.answers.get(type)) : pending;
    },
    seeded(initial: unknown): unknown {
      const before = state.initials;
      state.initials = [...before, initial];
      for (const seed of state.seeds) {
        if (seed.used || before.length < seed.after.length || !Object.is(initial, seed.initial)) continue;
        const run = before.slice(before.length - seed.after.length);
        if (!seed.after.every((want, i) => Object.is(run[i], want))) continue;
        seed.used = true;
        return seed.value;
      }
      return initial;
    },
    reset() {
      state.effects.clear();
      state.answers.clear();
      state.asked = [];
      state.seeds = [];
      state.initials = [];
    },
  };
  return state;
});

vi.mock("react", async (original) => {
  const react = await original<typeof import("react")>();
  /** Who called the effect: the frame after the seam's own. */
  const caller = () => {
    const frames = (new Error().stack ?? "").split("\n");
    const at = frames.findIndex((f) => f.includes("seamEffect"));
    return /at (?:[\w$]+\.)*([\w$]+)/.exec(frames[at + 1] ?? "")?.[1] ?? "";
  };
  /** The named components' effects, run during the render, again only when a dependency changes. */
  function seamEffect(run: () => void | (() => void), deps?: readonly unknown[]) {
    const last = react.useRef<readonly unknown[] | null>(null);
    const cleanup = react.useRef<void | (() => void)>(undefined);
    if (!seam.effects.has(caller())) return;
    const was = last.current;
    if (was && (!deps || (deps.length === was.length && deps.every((d, i) => Object.is(d, was[i]))))) return;
    last.current = deps ?? [];
    cleanup.current?.();
    cleanup.current = run();
  }
  return {
    ...react,
    useEffect: seamEffect,
    useLayoutEffect: seamEffect,
    useState: (initial?: unknown) => react.useState(seam.seeded(initial)),
  };
});
vi.mock("../src/ui/background", async (original) => ({
  ...(await original<typeof import("../src/ui/background")>()),
  call: (type: string) => seam.call(type),
}));

import { t } from "../src/i18n";
import { DEFAULT_PREFERENCES } from "../src/shared/preferences";
import { formatAda } from "../src/ui/format";
import { NetworkContext } from "../src/ui/network";
import { PreferencesContext } from "../src/ui/preferences";
import { ConnectRequest } from "../src/ui/screens/DappApprovals";

const ADA = 1_000_000n;
const token = { policyId: "16".repeat(28), assetName: "4f4e45", quantity: "1" };
type Locked = { lovelace: string; tokens: (typeof token)[]; utxos: number };

/** The worker's reading of the private side: 100 ₳ and a token over two UTxOs, `locked` of it locked by the user. */
const privateSide = (locked: Locked) => ({ lovelace: (100n * ADA).toString(), tokens: [token], utxos: 2, seedelfs: [], locked });
/** 60 ₳ and the token in the one UTxO the user locked on the UTxOs screen. */
const SIXTY: Locked = { lovelace: (60n * ADA).toString(), tokens: [token], utxos: 1 };
/** Both UTxOs locked. */
const ALL: Locked = { lovelace: (100n * ADA).toString(), tokens: [token], utxos: 2 };
const NONE: Locked = { lovelace: "0", tokens: [], utxos: 0 };

/** What a person reads of markup. */
const words = (markup: string) =>
  markup
    .replace(/<[^>]+>/g, " ")
    .replaceAll("&#x27;", "'")
    .replaceAll("&amp;", "&")
    .replaceAll("&quot;", '"')
    .replace(/\s+/g, " ")
    .trim();
const escaped = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
/** An ADA figure as the page's words have it, with no digit before it: "40 ₳", never the end of "140 ₳". */
const figure = (lovelace: bigint) => `(?<![\\d.,])${escaped(formatAda(lovelace.toString()))} ₳`;
/** The page's sentences, as a person reads them. */
const sentences = (page: string) => words(page).split(/(?<=[.!?])\s+/);
/** The sentences that call `lovelace` what's in the private balance, with no word of a lock in them. */
const calledTheBalance = (page: string, lovelace: bigint) =>
  sentences(page).filter((s) => new RegExp(`${figure(lovelace)} in your private balance`, "i").test(s) && !/\blocked\b/i.test(s));

/** The connect window, a private session chosen and `amount` typed, the worker's reading `side`: its markup. */
function privateForm(side: ReturnType<typeof privateSide>, amount: string, prefs: Partial<typeof DEFAULT_PREFERENCES> = {}): string {
  seam.effects.add("ConnectRequest");
  seam.answers.set("balances", { seedelf: side });
  // The choice: the first state that starts undefined. The amount: the one after the governance switch's and the
  // private balance's.
  seam.seeds.push({ after: [], initial: undefined, value: "private" }, { after: [false, undefined], initial: "", value: amount });
  return renderToStaticMarkup(
    createElement(
      NetworkContext.Provider,
      { value: "preprod" },
      createElement(
        PreferencesContext.Provider,
        { value: { prefs: { ...DEFAULT_PREFERENCES, hideBalances: false, ...prefs }, loaded: true, set: async () => undefined } },
        createElement(ConnectRequest, {
          approval: { kind: "connect", id: "a1", origin: "https://example.org", title: "Example", password: false },
          busy: false,
          held: false,
          onError: () => undefined,
          onAnswer: async () => false,
        } as never),
      ),
    ),
  );
}

/** The private session's Review: its label, and whether it's off. */
const review = (page: string) => {
  const button = /<button type="submit" class="primary"( disabled="")?>([^<]*)<\/button>/.exec(page);
  return { label: button?.[2], off: button?.[1] !== undefined };
};

