describe("a split route's leg that both of the runner's listings miss (chunk 51, r2still#2)", { timeout: 600_000 }, () => {
  it("comes back in the session's first return, through Lovejoin as approved, and never alone after it unsaid", async () => {
    const t = testBalances();
    await t.wallet.create(PHRASE, PASSWORD);
    t.koios.evaluation = AGREES;
    // A slot in preprod's Shelley era, for what the account signs (lovejoin-flows.test.ts).
    t.koios.tip = 110_000_000;
    t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
    await t.deps.preferences.set({ lovejoinDepth: 1 });
    const sessions = runner(t, pooled(t, [ADA_POOL]));

    // Session 0 sold MIN for ADA through Lovejoin, as approved, one wave deep; Minswap split it into two orders,
    // SWAP_TX#0 and #2, both landed. Its funding (FUND) paid it the 5 ₳ collateral too.
    const now = t.clock.now;
    const FUND = "01".repeat(32);
    const orders = [`${SWAP_TX}#0`, `${SWAP_TX}#2`];
    await t.store.set("sessions.preprod", {
      next: 1,
      sessions: [
        {
          index: 0,
          ownStake: true,
          createdAt: now,
          txs: [
            { kind: "out", txHash: FUND, at: now, confirmed: true },
            { kind: "swap", txHash: SWAP_TX, at: now, confirmed: true, orders, minAmountOut: "40000000" },
          ],
          swap: { ...ASK, tokenIn: MIN, tokenOut: "lovelace", amount: "906594100", amountOut: "41000000", minAmountOut: "40000000" },
          auto: {
            approved: { minAmountOut: "40000000", fund: { lovelace: "16000000", tokens: [] } },
            direct: false,
            lovejoin: { depth: 1, delay: "1-6", box: "5000000" },
          },
        },
      ],
    });
    // The account: the swap's change, the collateral, and leg 1's fill (20 ₳), listed; both orders spent at the DEX's
    // contract, as utxo_info reads them from the first run on; the 5 ₳ pool's 20 boxes of other people's.
    t.koios.addedToAccounts.push(
      atSession(SWAP_TX, 1, "2000000"),
      atSession(FUND, 1, "5000000"),
      ...orders.map((o) => orderRow(SWAP_TX, Number(o.split("#")[1]))),
      atSession("aa".repeat(32), 0, "20000000"),
      ...ADA_ROWS,
    );
    for (const o of orders) t.koios.spent.add(o);
    // Leg 2's fill (20 ₳) is in the block utxo_info's backend has and the listings' backend doesn't yet: neither of the
    // first run's two listings holds it. That backend has caught up by the next run, 15 s later.
    const LATE = `${"bb".repeat(32)}#0`;
    const late = atSession("bb".repeat(32), 0, "20000000");
    const book = async () => (await t.store.get<{ sessions: Book[] }>("sessions.preprod"))!.sessions[0]!;
    const before = t.koios.submitted.length;
    // The session's first return as the runner sent it: a chain through Lovejoin, kept as it's sent, or one that came
    // back directly.
    const firstReturn = async (): Promise<Uint8Array[]> => {
      const chain = await t.wallet.withKeys(() => t.session.get<{ txs: Array<{ txCbor: string }> }>(`${SESSION_CHAIN_PREFIX}preprod.0`));
      if (chain) return chain.txs.map((x) => Uint8Array.from(Buffer.from(x.txCbor, "hex")));
      return (await book()).txs.some((x) => x.kind === "back") ? t.koios.submitted.slice(before) : [];
    };

    // The run that first reads every order spent, its listings behind; then the leg is listed. A fix may wait a run
    // for it, so up to three runs until the first return goes.
    await sessions.advance("preprod", 0, true);
    t.koios.addedToAccounts.push(late);
    let first = await firstReturn();
    for (let run = 1; run < 3 && !first.length; run++) {
      await sessions.advance("preprod", 0, true);
      first = await firstReturn();
    }
    expect(first.length).toBeGreaterThan(0);

    // It lands, and the runner runs on until the session closes: whatever is left at the account comes back.
    t.koios.confirmations = 1;
    for (let run = 0; run < 10 && !(await book()).closedAt; run++) {
      for (const tx of t.koios.submitted) for (const o of txInputs(tx)) t.koios.spent.add(o);
      await sessions.advance("preprod", 0, true);
    }
    const s = await book();
    const view = await sessions.advance("preprod", 0, true);
    const firstTakesLate = first.some((tx) => txInputs(tx).includes(LATE));
    // Where the leg came back otherwise: in a return of its own after the first, with no deposit or mix after the
    // first return's, so directly.
    const lateTx = t.koios.submitted.find((tx) => txInputs(tx).includes(LATE));
    const lateHash = lateTx ? txIdOf(lateTx) : undefined;
    const later = s.txs.slice(s.txs.findIndex((x) => x.kind === "back" && !x.replaced) + 1).filter((x) => !x.replaced);
    const lateAloneDirect =
      !firstTakesLate && later.some((x) => x.kind === "back" && x.txHash === lateHash) && !later.some((x) => x.kind === "deposit" || x.kind === "mix");

    expect
      .soft({
        closed: s.closedAt !== undefined,
        // The first return takes leg 2's fill.
        firstTakesLate,
        // One return: the chain's, nothing after it.
        returns: s.txs.filter((x) => x.kind === "back" && !x.replaced).length,
        // Nothing came back saying Lovejoin was left out.
        lovejoinSkipped: s.lovejoinSkipped,
      })
      .toEqual({ closed: true, firstTakesLate: true, returns: 1, lovejoinSkipped: undefined });
    // And where the swap's own leg did come back alone and directly, its page says Lovejoin was left out of it, never
    // nothing, as for a stranger's 2 ₳ (e2b#2).
    expect
      .soft(
        { lateAloneDirect, pageSays: view.lovejoinSkipped },
        "the swap's own leg came back alone and directly, and the page says nothing of it",
      )
      .toSatisfy(({ lateAloneDirect: alone, pageSays }: { lateAloneDirect: boolean; pageSays?: string }) => !alone || pageSays !== undefined);
  });
});

// Chunk 51, r2time#1 (the review of its own merged fixes): Bring one back paid from the public account reads which
// account pays twice. withdrawNow reads it as it's pressed, for the watch's paysAccounts (fdd3b8b2, e5#2's sibling);
// withdrawOne reads, builds and signs with whichever account is active after its pool's reward-account read. A switch
// in between, which handlers.ts lets through, has one account pay while the watch names the other. Whichever account a
// fix makes pay, the watch names the one whose UTxO the transaction spends, and its landing reads that account again
// and no other: the rule lovejoin-release-rules.test.ts pins with no switch. A fix that refuses the build once the
// account moved under it sends nothing, which holds too.
import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import { handle, type Context } from "../src/background/handlers";
import type { KoiosUtxo } from "../src/background/koios";
import { LovejoinService, type PoolRef } from "../src/background/lovejoin";
import { pendingKey } from "../src/background/pending";
import { SESSION_BALANCES_PREFIX, SESSION_PRIVATE_STALE_PREFIX } from "../src/background/wallet";
import { txIdOf } from "./fixtures/cbor";
import { bech32 } from "./fixtures/bech32";
import { koiosPreprod, loadTestWasm, testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const PHRASE = (vectors("cardano_account.json") as Array<{ account: number; phrase: string }>).find(
  (v) => v.account === 0 && v.phrase.split(" ").length === 12,
)!.phrase;
const SLOW = { timeout: 240_000 };
const POOL = (JSON.parse(readFileSync(new URL("./fixtures/lovejoin-pool-preprod.json", import.meta.url), "utf8")) as { pool: KoiosUtxo[] }).pool;
const FOUND = JSON.parse(readFileSync(new URL("../../wasm/tests/fixtures/lovejoin-v2-token-pool-preprod.json", import.meta.url), "utf8")) as {
  seed: { txHash: string; txIndex: number };
  reference: KoiosUtxo;
  scripts: KoiosUtxo[];
};
const TOKEN_POOL: PoolRef = { reference: FOUND.reference, seed: FOUND.seed, scripts: FOUND.scripts };
const VIEW = JSON.parse(loadTestWasm().lovejoinVerifyPool(JSON.stringify({ network: "preprod", pool: TOKEN_POOL }))) as {
  id: string;
  mixBoxHash: string;
  token: { policyId: string; assetName: string; quantity: string };
};
const TOKEN = VIEW.id;
const Q = BigInt(VIEW.token.quantity);
const TOKEN_ADDRESS = bech32("addr_test", Uint8Array.from([0x70, ...Buffer.from(VIEW.mixBoxHash, "hex")]));
/** The token pool's mix_logic reward account: what withdrawOne's first request (rewardsIn) asks account_info about. */
const LOGIC = JSON.parse(loadTestWasm().lovejoinMixLogic(JSON.stringify({ network: "preprod", poolRef: TOKEN_POOL }))) as { stake: string };
const AGREES = { jsonrpc: "2.0", method: "evaluateTransaction", result: [] };
/** A byte three times preprod's price: the 2 ₳ box can't pay its own way back, so the public account pays. */
const DEAR = { coins_per_utxo_size: "12930" };

type T = ReturnType<typeof testBalances>;

function pooled(t: T): LovejoinService {
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  return new LovejoinService({
    ...t.deps,
    wasm: {
      ...wasm,
      finishLovejoinWithdraw: (request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => [TOKEN_POOL],
    random: () => 0.5,
  });
}

/** The worker's handlers over `t` and `lj`: the switch goes through account-use's own gate. */
const contextOf = (t: T, lj: LovejoinService) =>
  ({
    ...(t as unknown as Context),
    lovejoin: lj,
    wasm: loadTestWasm(),
    connector: async (on: boolean) => on,
    version: "1.0.0",
    network: "preprod",
    networks: ["preprod"],
  }) as Context;

/** Account 0's: one of the recorded account's UTxOs, made again as `tx`'s with `value`. */
function atAccount(tx: string, value: string): KoiosUtxo {
  const [first] = Object.values(koiosPreprod.accounts)[0]!.account_utxos.filter((u) => BigInt(u.value) > 1_000_000_000n);
  return { ...first!, tx_hash: tx.repeat(32), tx_index: 0, value, asset_list: [] as never };
}

/** Account `index`'s: a UTxO of ADA alone at its receive address 0/0. */
async function atAccountIndex(t: T, index: number, tx: string, value: string): Promise<KoiosUtxo> {
  const [address, key] = await t.wallet.withAccount(index, ({ cardano }) => [cardano.receiveAddress(t.deps.wasm.Network.Preprod, 0), cardano.paymentKeyHash(0, 0)]);
  const [first] = Object.values(koiosPreprod.accounts)[0]!.account_utxos.filter((u) => BigInt(u.value) > 1_000_000_000n);
  return {
    ...first!,
    tx_hash: tx.repeat(32),
    tx_index: 0,
    address,
    value,
    stake_address: null,
    payment_cred: key,
    inline_datum: null,
    datum_hash: null,
    asset_list: [],
    reference_script: null,
  } as unknown as KoiosUtxo;
}

async function datum(t: T, ours: boolean): Promise<string> {
  const wasm = loadTestWasm();
  if (ours) return t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
  const stranger = wasm.SeedelfKey.fromHex("01".repeat(32));
  const bytes = Buffer.from(wasm.registerToDatum(wasm.rerandomize(stranger.baseRegister()))).toString("hex");
  stranger.free();
  return bytes;
}

/** A box in the token pool, the wallet's or a stranger's, a mix having moved it `hours` ago. */
async function tokenBox(t: T, tx: string, ours = true, hours = 5): Promise<KoiosUtxo> {
  t.koios.txSpends.set(tx.repeat(32), [{ payment_addr: { bech32: TOKEN_ADDRESS, cred: VIEW.mixBoxHash } }]);
  return {
    ...POOL[0]!,
    tx_hash: tx.repeat(32),
    tx_index: 0,
    address: TOKEN_ADDRESS,
    payment_cred: VIEW.mixBoxHash,
    value: "2000000",
    block_time: Math.floor(t.clock.now / 1000) - hours * 3600,
    datum_hash: null,
    inline_datum: { bytes: await datum(t, ours), value: {} },
    asset_list: [{ policy_id: VIEW.token.policyId, asset_name: VIEW.token.assetName, quantity: Q.toString(), decimals: 0, fingerprint: "asset1ljtest" } as never],
  } as KoiosUtxo;
}

const strangers = (t: T) => Promise.all(Array.from({ length: 12 }, (_, i) => tokenBox(t, (0x60 + i).toString(16), false)));

/** Holds the first account_info request about `stake` until released; `hit` once it's asked. */
function holdAccountInfo(t: T, stake: string) {
  const real = t.koios.fetch;
  let release!: () => void;
  let reached!: () => void;
  const gate = new Promise<void>((r) => (release = r));
  const hit = new Promise<void>((r) => (reached = r));
  let once = true;
  t.koios.fetch = async (url, init) => {
    if (once && new URL(url).pathname.endsWith("/account_info") && String(init?.body ?? "").includes(stake)) {
      once = false;
      reached();
      await gate;
    }
    return real(url, init);
  };
  return { hit, release };
}

/** The private history's entry for `txHash`. */
const historyOf = async (t: T, txHash: string) =>
  (await t.store.get<{ entries: Array<{ txHash: string; origin?: { id: string; origin: string } }> }>("history.preprod"))!.entries.find(
    (e) => e.txHash === txHash,
  );

describe("chunk 51, r2time#1: Bring one back paid from the public account, the account switched while it builds", SLOW, () => {
  it("watches the account whose UTxO pays, and reads that account again as it lands, and no other", async () => {
    // `landOn`: the account the wallet is on as it lands: the one switched to, or back on the one it was pressed on.
    for (const landOn of [1, 0]) {
      const t = testBalances();
      await t.wallet.create(PHRASE, PASSWORD);
      t.koios.evaluation = AGREES;
      t.koios.tip = 110_000_000;
      const lj = pooled(t);
      const ctx = contextOf(t, lj);
      const mine = await tokenBox(t, "f1", true, 7);
      await t.accounts.add(1);
      // Each account can pay: 20 ₳, and 5 ₳ for its collateral.
      const zero = [atAccount("e1", "20000000"), atAccount("e5", "5000000")];
      const one = [await atAccountIndex(t, 1, "d1", "20000000"), await atAccountIndex(t, 1, "d5", "5000000")];
      t.koios.addedToAccounts.push(...zero, ...one, ...POOL, mine, ...(await strangers(t)));
      t.koios.params = DEAR;
      await t.balances.get("preprod");
      const sent = t.koios.submitted.length;

      // Pressed on account 0. While Koios answers withdrawOne's first request, the user picks account 1 (Account 2):
      // account-use's gate lets it through, as nothing of account 0's is maybe sent and no public mix is being sent.
      const hold = holdAccountInfo(t, LOGIC.stake);
      const going = lj.withdrawNow("preprod", { txHash: mine.tx_hash, txIndex: 0, pool: TOKEN }, false, true);
      await hold.hit;
      await handle({ type: "account-use", index: 1 }, ctx);
      expect(await t.accounts.active()).toBe(1);
      hold.release();
      const outcome = await going.then(
        (pending) => ({ pending }),
        (error: unknown) => ({ error }),
      );
      const watch = await t.wallet.withKeys(() => t.session.get<{ txHash: string; paysAccounts?: number[]; toAccount?: true }>(pendingKey("preprod")));
      if ("error" in outcome) {
        // Refused once the account moved under it: nothing sent, nothing watched.
        expect(t.koios.submitted.length, `landing on ${landOn}`).toBe(sent);
        expect(watch, `landing on ${landOn}`).toBeUndefined();
        continue;
      }
      const { pending } = outcome;
      expect(t.koios.submitted.length).toBe(sent + 1);
      // Which account paid, by the UTxO its transaction spends.
      const inputs = txInputs(t.koios.submitted.at(-1)!);
      const spends = (us: KoiosUtxo[]) => us.some((u) => inputs.includes(`${u.tx_hash}#${u.tx_index}`));
      const payer = spends(one) ? 1 : spends(zero) ? 0 : undefined;
      expect(payer, `inputs ${inputs.join(", ")}`).toBeDefined();
      expect(spends(one) && spends(zero)).toBe(false);
      // The history of what comes back ties the account whose keys signed it (Withdrawing `ties`, PRIV-3).
      expect((await historyOf(t, pending.txHash))?.origin?.id).toBe(`box:${pending.txHash}+public:${payer}`);

      // The watch names that account, as the history does.
      expect(watch?.txHash).toBe(pending.txHash);
      expect.soft(watch?.paysAccounts, `landing on ${landOn}: the watch names the account that paid (${payer})`).toEqual([payer]);

      // On account `landOn` as it lands (back on account 0 through the same gate: nothing maybe sent), Home's reading
      // of it kept.
      if (landOn !== (await t.accounts.active())) await handle({ type: "account-use", index: landOn }, ctx);
      expect(await t.accounts.active()).toBe(landOn);
      await t.balances.get("preprod");
      expect(await t.wallet.withKeys(() => t.session.get(SESSION_BALANCES_PREFIX + "preprod"))).toBeDefined();
      t.koios.confirmations = 1;
      expect(await t.pending.pending("preprod")).toMatchObject({ kind: "lovejoin-withdraw", txHash: pending.txHash, confirmations: 1 });
      // On the account that paid, both sides are read again; on another, the private side alone (e5#2, 34d's review 9).
      const kept = (await t.wallet.withKeys(() => t.session.get(SESSION_BALANCES_PREFIX + "preprod"))) !== undefined;
      const privateOnly = await t.wallet.withKeys(() => t.session.get(SESSION_PRIVATE_STALE_PREFIX + "preprod"));
      const paidHere = payer === landOn;
      expect
        .soft({ kept, privateOnly }, `landing on ${landOn}, paid by ${payer}`)
        .toEqual(paidHere ? { kept: false, privateOnly: undefined } : { kept: true, privateOnly: true });
    }
  });
});

// Chunk 51, finding r2time#2 (e4a#1's class, after its phrase-pin fix): what the worker writes once a submit or a
// look has answered goes to whichever phrase is in by then. A due box's withdraw, the alarm's own, goes to Koios under
// phrase A; while Koios answers, the user removes the wallet, which lists nothing open (a withdraw on its way isn't
// among what Remove wallet lists), and restores phrase B. When Koios answers, A's box-back entry is sealed into B's
// private history: withdrawOne's write after its submit, and settleWithdrawing's for one Koios didn't answer, seen
// later. A payment's submit the same, after Remove wallet's second yes: its watch goes into B's session, and its entry
// into B's history (pending.ts submitWatched). Each expectation is the right behaviour, and fails on the tree as it is.
import { describe, expect, it } from "vitest";

import { Collateral } from "../src/background/collateral";
import { handle, type Context } from "../src/background/handlers";
import { LovejoinService } from "../src/background/lovejoin";
import { pendingKey, submitWatched } from "../src/background/pending";
import { NetworkChoice } from "../src/background/preferences";
import { SESSION_TRANSFER } from "../src/background/transfer";
import { SESSION_UNLOCKED_AT } from "../src/background/wallet";
import type { NetworkName } from "../src/networks";
import type { AtStake, Message } from "../src/shared/rpc";
import { txIdOf } from "./fixtures/cbor";
import { loadTestWasm, testBalances, transferPreprod, vectors } from "./fakes";
import { ADA, ADA_POOL, ADA_ROWS, adaBox, madeByAdaMix, ownDatum } from "./v2-pools";

const PASSWORD = "correct horse battery";
const HOUR = 3_600_000;
const vector = (words: number) => vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;
/** Phrase A: the wallet the withdraw or the payment goes from (owned-utxos.json's owner). */
const A = vector(12).phrase as string;
/** Phrase B: restored once A is removed, while Koios answers A's. */
const B = vector(24).phrase as string;
/** B's first receiving address: which phrase is in. */
const B_RECEIVE = vector(24).preprod.receive_0 as string;
/** Each withdraw is built and measured in WebAssembly. */
const SLOW = { timeout: 120_000 };

type T = ReturnType<typeof testBalances>;

function context(t: T, lovejoin = t.lovejoin): Context {
  const networks: NetworkName[] = ["preprod", "mainnet"];
  return {
    ...(t as unknown as Context),
    lovejoin,
    wasm: loadTestWasm(),
    connector: async (on) => on,
    version: "1.0.0",
    network: "preprod",
    networks,
    networkChoice: new NetworkChoice(t.local, networks),
  };
}

const ask = (message: Message, ctx: Context) => handle(message, ctx);

/** Settings' Remove wallet, its screen reading first what's open (returned), then B restored by its phrase. */
async function removeAndRestoreB(ctx: Context, force = false): Promise<AtStake[]> {
  const listed = (await ask({ type: "reset-check" }, ctx)) as AtStake[];
  await ask({ type: "reset-wallet", ...(force ? { force: true } : {}) }, ctx);
  await ask({ type: "restore-wallet", phrase: B, password: PASSWORD }, ctx);
  return listed;
}

/**
 * As lovejoin-withdraw-submit.test.ts has it: A unlocked an hour ago, its unlock's draws made, one box of its own in
 * v2's 5 ₳ pool, due; giveme.my's witness stood in for, so the withdraw that goes is submitted.
 */
async function due() {
  const t = testBalances({ pools: [ADA_POOL] });
  await t.wallet.create(A, PASSWORD);
  madeByAdaMix(t.koios, "e1".repeat(32));
  const owned = adaBox("e1", await ownDatum(t.wallet), t.clock.now);
  t.koios.addedToAccounts.push(...ADA_ROWS, owned);
  const unlocked = t.clock.now - HOUR;
  await t.wallet.withKeys(() => t.session.set(SESSION_UNLOCKED_AT, unlocked));
  await t.store.set("lovejoin.preprod", { due: [], pools: { [ADA]: { due: [t.clock.now - HOUR] } }, unlock: unlocked });
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  const lovejoin = new LovejoinService({
    ...t.deps,
    wasm: {
      ...wasm,
      finishLovejoinWithdraw: (request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => [ADA_POOL],
  });
  return { t, lovejoin, ctx: context(t, lovejoin) };
}

/** The transactions B's private Activity lists. */
const bHistory = async (t: T) => (await t.activity.seedelf("preprod")).map((e) => e.txHash);

describe("what a submit or a look writes once it answers, after Remove wallet and a restore of another phrase (r51 r2time#2)", () => {
  it("a due box's withdraw Koios takes meanwhile: none of it in B's history", SLOW, async () => {
    const { t, lovejoin, ctx } = await due();
    let listed: AtStake[] | undefined;
    const real = t.koios.fetch;
    t.koios.fetch = async (url, init) => {
      if (!url.endsWith("/submittx")) return real(url, init);
      // Koios takes it and answers slowly (a 429's hold before it, a node slow to say): the user removes the wallet
      // and restores B meanwhile.
      const taken = await real(url, init);
      listed = await removeAndRestoreB(ctx);
      return taken;
    };
    await lovejoin.withdrawDue("preprod", false, t.clock.now).catch(() => undefined);
    t.koios.fetch = real;
    const sent = txIdOf(t.koios.submitted.at(-1)!);

    // Remove wallet listed nothing open, so it took no second yes; and B is the wallet now.
    expect(listed, "Remove wallet's list").toEqual([]);
    expect((await t.wallet.account("preprod")).receiveAddress).toBe(B_RECEIVE);
    // A's box came back to A: B's private Activity never lists it as a box of B's back from Lovejoin.
    expect(await bHistory(t), "B's private Activity").not.toContain(sent);
  });

  it("one Koios didn't answer, seen on chain by the next run's look: none of it in B's history", SLOW, async () => {
    const { t, lovejoin, ctx } = await due();
    const real = t.koios.fetch;
    // Koios takes it, and its answer never comes (a 504): it may have gone through, so it's kept and looked for.
    t.koios.fetch = async (url, init) => {
      if (!url.endsWith("/submittx")) return real(url, init);
      await real(url, init);
      return new Response("", { status: 504 });
    };
    await lovejoin.withdrawDue("preprod", false, t.clock.now).catch(() => undefined);
    const sent = txIdOf(t.koios.submitted.at(-1)!);

    // The alarm's next run looks for it (tx_status): the user removes the wallet and restores B while Koios answers,
    // and it's on chain.
    t.koios.confirmations = 1;
    let listed: AtStake[] | undefined;
    t.koios.fetch = async (url, init) => {
      if (listed === undefined && url.endsWith("/tx_status") && String(init?.body).includes(sent)) listed = await removeAndRestoreB(ctx);
      return real(url, init);
    };
    await lovejoin.withdrawDue("preprod", false, t.clock.now).catch(() => undefined);
    t.koios.fetch = real;

    expect(listed, "Remove wallet's list").toEqual([]);
    expect((await t.wallet.account("preprod")).receiveAddress).toBe(B_RECEIVE);
    expect(await bHistory(t), "B's private Activity").not.toContain(sent);
  });

  it("a payment Koios takes meanwhile, Remove wallet's second yes given: neither B's watch nor B's history", SLOW, async () => {
    const t = testBalances();
    const ctx = context(t);
    await ask({ type: "restore-wallet", phrase: A, password: PASSWORD }, ctx);
    // A private payment, reviewed and kept for Send.
    t.koios.evaluation = transferPreprod.evaluation;
    const built = await t.transfer.build("preprod", [{ to: transferPreprod.to, lovelace: "2000000", tokens: [] }]);
    const kept = (await t.wallet.withKeys(() => t.session.get<{ txCbor: string }>(SESSION_TRANSFER)))!;
    let listed: AtStake[] | undefined;
    const real = t.koios.fetch;
    t.koios.fetch = async (url, init) => {
      if (!url.endsWith("/submittx")) return real(url, init);
      const taken = await real(url, init);
      // Remove wallet lists it, maybe sent (written ahead), and the user says yes twice; then B is restored.
      listed = await removeAndRestoreB(ctx, true);
      return taken;
    };
    const sending = { network: "preprod", txHash: built.txHash, kind: "transfer", txCbor: kept.txCbor, key: SESSION_TRANSFER, kept } as const;
    await submitWatched(t.deps, { ...sending, summary: built, contract: true, again: false }).catch(() => undefined);
    t.koios.fetch = real;

    expect(listed?.find((a) => a.network === "preprod")?.maybeSent?.txHash, "Remove wallet's list").toBe(built.txHash);
    expect((await t.wallet.account("preprod")).receiveAddress).toBe(B_RECEIVE);
    // B's Home watches nothing of A's, and B's private Activity lists none of A's payments.
    expect.soft(await t.wallet.withKeys(() => t.session.get(pendingKey("preprod"))), "B's watch").toBeUndefined();
    expect.soft(await bHistory(t), "B's private Activity").not.toContain(built.txHash);
  });
});

